appsmith.onReady(function () {
  var navMenu = document.getElementById('navMenu');
  var reportModelUnlisten = null;
  var reportRefreshInterval = null;
  function cleanupReportsModule() {
    if (typeof reportModelUnlisten === 'function') {
      try {
        reportModelUnlisten();
      } catch (e) {
        /* No bloquear la navegación por un error de limpieza */
      }
      reportModelUnlisten = null;
    }
    if (reportRefreshInterval !== null) {
      clearInterval(reportRefreshInterval);
      reportRefreshInterval = null;
    }
  }
  function decodeB64(s) {
    if (!s) {
      return null;
    }
    try {
      return JSON.parse(decodeURIComponent(escape(atob(s))));
    } catch (e) {
      return null;
    }
  }
  function esc(s) {
    var d = document.createElement('div');
    d.textContent = s == null ? '' : String(s);
    return d.innerHTML;
  }
  var PLAT_NAMES = {
    instagram: 'Instagram',
    tiktok: 'TikTok',
    facebook: 'Facebook',
    x: 'X (Twitter)',
    reddit: 'Reddit',
    threads: 'Threads',
    bluesky: 'Bluesky',
    snapchat: 'Snapchat',
    truth_social: 'Truth Social',
    youtube: 'YouTube',
    rumble: 'Rumble',
    twitch: 'Twitch',
    kwai: 'Kwai',
    kick: 'Kick',
    linkedin: 'LinkedIn',
    github: 'GitHub',
    telegram: 'Telegram',
    tiktok_shop: 'TikTok Shop',
    facebook_marketplace: 'FB Marketplace',
    facebook_events: 'FB Events',
    facebook_ad_library: 'FB Ad Library',
    tiktok_ad_library: 'TikTok Ad Library',
    google_ad_library: 'Google Ad Library',
    linkedin_ad_library: 'LinkedIn Ad Library',
    spotify: 'Spotify',
    apple_music: 'Apple Music',
    soundcloud: 'SoundCloud',
    google: 'Google',
    pinterest: 'Pinterest'
  };
  var PLAT_COLORS = {
    instagram: '#2E9BCB',
    tiktok: '#2F323B',
    facebook: '#2972A9',
    x: '#2F323B',
    reddit: '#585A61',
    threads: '#585A61',
    bluesky: '#2E9BCB',
    snapchat: '#2972A9',
    truth_social: '#585A61',
    youtube: '#2972A9',
    rumble: '#585A61',
    twitch: '#2E9BCB',
    kwai: '#2972A9',
    kick: '#585A61',
    linkedin: '#2972A9',
    github: '#2F323B',
    telegram: '#2E9BCB',
    tiktok_shop: '#585A61',
    facebook_marketplace: '#2972A9',
    facebook_events: '#2E9BCB',
    facebook_ad_library: '#2972A9',
    tiktok_ad_library: '#2E9BCB',
    google_ad_library: '#2972A9',
    linkedin_ad_library: '#2F323B',
    spotify: '#585A61',
    apple_music: '#2E9BCB',
    soundcloud: '#2972A9',
    google: '#585A61',
    pinterest: '#2F323B'
  };
  function platName(code) {
    return PLAT_NAMES[code] || code;
  }
  function platColor(code) {
    return PLAT_COLORS[code] || '#2972A9';
  }
  var role = 'viewer';
  try {
    var model = appsmith.model || {};
    role = model.userRole || 'viewer';
    var email = model.userEmail || '';
    var active = model.active || 'dashboard';
    document.getElementById('userEmail').textContent = email;
    document.getElementById('userRole').textContent = role.toUpperCase();
    document.getElementById('userAvatar').textContent = email.charAt(0).toUpperCase() || 'A';
    var MENU = [{
      section: 'Análisis',
      items: [{
        id: 'dashboard',
        label: 'Dashboard',
        roles: ['admin', 'analyst', 'viewer']
      }, {
        id: 'mentions',
        label: 'Menciones',
        roles: ['admin', 'analyst', 'viewer']
      }, {
        id: 'analytics',
        label: 'Analítica',
        roles: ['admin', 'analyst']
      }, {
        id: 'competitors',
        label: 'Competencia',
        roles: ['admin', 'analyst']
      }]
    }, {
      section: 'Gestión',
      items: [{
        id: 'targets',
        label: 'Objetivos',
        roles: ['admin', 'analyst']
      }, {
        id: 'alerts',
        label: 'Alertas',
        roles: ['admin', 'analyst', 'viewer']
      }, {
        id: 'reports',
        label: 'Reportes',
        roles: ['admin', 'analyst', 'viewer']
      }]
    }, {
      section: 'Administración',
      items: [{
        id: 'tasks',
        label: 'Tareas de Scrapeo',
        roles: ['admin']
      }, {
        id: 'integrations',
        label: 'Integraciones',
        roles: ['admin']
      }, {
        id: 'users',
        label: 'Usuarios',
        roles: ['admin']
      }, {
        id: 'roles',
        label: 'Roles y Permisos',
        roles: ['admin']
      }, {
        id: 'audit',
        label: 'Auditoría',
        roles: ['admin']
      }, {
        id: 'settings',
        label: 'Configuración',
        roles: ['admin']
      }, {
        id: 'billing',
        label: 'Plan y Suscripción',
        roles: ['admin']
      }]
    }];
    var TITLES = {
      dashboard: 'Dashboard Ejecutivo',
      mentions: 'Menciones',
      analytics: 'Analítica',
      competitors: 'Competencia',
      targets: 'Objetivos Monitoreados',
      alerts: 'Alertas',
      reports: 'Reportes',
      tasks: 'Tareas de Scrapeo',
      integrations: 'Integraciones',
      users: 'Usuarios',
      roles: 'Roles y Permisos',
      audit: 'Auditoría',
      settings: 'Configuración',
      billing: 'Plan y Suscripción'
    };
    navMenu.innerHTML = '';
    MENU.forEach(function (section) {
      var visible = [];
      for (var i = 0; i < section.items.length; i++) {
        if (section.items[i].roles.indexOf(role) !== -1) {
          visible.push(section.items[i]);
        }
      }
      if (visible.length === 0) {
        return;
      }
      var containsActive = false;
      for (var j = 0; j < visible.length; j++) {
        if (visible[j].id === active) {
          containsActive = true;
        }
      }
      var group = document.createElement('li');
      group.className = 'nav-group' + (containsActive ? '' : ' collapsed');
      var head = document.createElement('div');
      head.className = 'nav-section-head';
      var headLabel = document.createElement('span');
      headLabel.textContent = section.section;
      head.appendChild(headLabel);
      head.addEventListener('click', function () {
        if (group.classList.contains('collapsed')) {
          group.classList.remove('collapsed');
        } else {
          group.classList.add('collapsed');
        }
      });
      group.appendChild(head);
      var list = document.createElement('ul');
      list.className = 'nav-group-items';
      visible.forEach(function (item) {
        var li = document.createElement('li');
        li.className = 'nav-item' + (item.id === active ? ' active' : '');
        li.textContent = item.label;
        li.addEventListener('click', function () {
          /*
           * IMPORTANTE:
           * cerramos cualquier listener del módulo Reportes
           * antes de abandonar la página.
           */
          cleanupReportsModule();
          appsmith.triggerEvent('go_' + item.id);
        });
        list.appendChild(li);
      });
      group.appendChild(list);
      navMenu.appendChild(group);
    });
    document.getElementById('viewTitle').textContent = TITLES[active] || 'Dashboard Ejecutivo';
    document.getElementById('logoutBtn').addEventListener('click', function () {
      cleanupReportsModule();
      appsmith.triggerEvent('onLogout');
    });
  } catch (errShell) {
    navMenu.innerHTML = '<li style="color:#A7CDDE;padding:12px;font-size:11px;">' + 'ERROR SHELL: ' + errShell.message + '</li>';
    return;
  }
  if ((appsmith.model || {}).active === 'reports') {
    try {
      initReportsModule();
    } catch (errMod) {
      var area = document.getElementById('contentArea');
      if (area) {
        area.innerHTML = '<div style="' + 'color:#2F323B;' + 'background:rgba(167,205,222,0.18);' + 'border:1px solid rgba(167,205,222,0.65);' + 'border-radius:10px;' + 'padding:14px;' + 'font-size:12px;' + '">' + 'ERROR MODULO: ' + errMod.message + '</div>';
      }
    }
  }
  function renderReport(data) {
    var area = document.getElementById('contentArea');
    if (!area) {
      return;
    }
    if (!data) {
      area.innerHTML = '<div class="empty-state">' + '<h4>Cargando reporte…</h4>' + '<p>Selecciona un periodo para generar el reporte.</p>' + '</div>';
      return;
    }
    var k = data.kpis || {};
    var plats = data.plataformas || [];
    var top = data.top || [];
    var menc = data.menciones || [];
    var dias = String(data.dias || 7);
    var opts = ['1', '7', '30', '90'].map(function (v) {
      var label = v === '1' ? 'Últimas 24 horas' : 'Últimos ' + v + ' días';
      return '<option value="' + v + '"' + (v === dias ? ' selected' : '') + '>' + label + '</option>';
    }).join('');
    var platRows = '';
    plats.forEach(function (p) {
      platRows += '<tr>' + '<td>' + '<span class="plat-badge" style="background:' + platColor(p.platform) + '">' + esc(platName(p.platform)) + '</span>' + '</td>' + '<td>' + esc(p.posts) + '</td>' + '<td>' + esc(p.reacciones) + '</td>' + '<td>' + esc(p.comentarios) + '</td>' + '</tr>';
    });
    var mencRows = '';
    menc.forEach(function (m) {
      mencRows += '<tr>' + '<td>' + '<span class="plat-badge" style="background:' + platColor(m.platform) + '">' + esc(platName(m.platform)) + '</span>' + '</td>' + '<td>' + esc(m.menciones) + '</td>' + '<td>' + esc(m.autores) + '</td>' + '</tr>';
    });
    var topRows = '';
    top.forEach(function (t) {
      var txt = (t.content_text || '').replace(/\s+/g, ' ').slice(0, 90);
      if ((t.content_text || '').length > 90) {
        txt += '…';
      }
      topRows += '<tr>' + '<td>' + '<span class="plat-badge" style="background:' + platColor(t.platform) + '">' + esc(platName(t.platform)) + '</span>' + '</td>' + '<td class="cell-strong">' + esc(txt) + '</td>' + '<td>' + esc(t.reacciones) + '</td>' + '<td>' + esc(t.comentarios) + '</td>' + '<td class="cell-muted">' + esc(t.published_at ? String(t.published_at).slice(0, 10) : '') + '</td>' + '</tr>';
    });
    var ventanaLabel = dias === '1' ? 'últimas 24 horas' : 'últimos ' + dias + ' días';
    area.innerHTML = '<section class="form-panel">' + '<div class="panel-head">' + '<h3>Periodo del reporte</h3>' + '<span class="kpi-sub">' + 'ventana activa: ' + esc(ventanaLabel) + '</span>' + '</div>' + '<div class="field" style="max-width:240px;">' + '<label class="field-label" for="f_dias">' + 'Ventana de análisis' + '</label>' + '<select id="f_dias" class="sl-input">' + opts + '</select>' + '</div>' + '</section>' + '<div class="kpi-grid">' + '<div class="kpi-card">' + '<span class="kpi-label">Publicaciones</span>' + '<span class="kpi-value">' + esc(k.posts || 0) + '</span>' + '<span class="kpi-sub">' + 'en la ventana seleccionada' + '</span>' + '</div>' + '<div class="kpi-card">' + '<span class="kpi-label">Reacciones</span>' + '<span class="kpi-value">' + esc(k.reacciones || 0) + '</span>' + '<span class="kpi-sub">' + 'en la ventana seleccionada' + '</span>' + '</div>' + '<div class="kpi-card">' + '<span class="kpi-label">Comentarios</span>' + '<span class="kpi-value">' + esc(k.comentarios || 0) + '</span>' + '<span class="kpi-sub">' + 'en posts de la ventana' + '</span>' + '</div>' + '<div class="kpi-card">' + '<span class="kpi-label">' + 'Engagement promedio' + '</span>' + '<span class="kpi-value">' + esc(k.engagement_promedio || 0) + '</span>' + '<span class="kpi-sub">' + 'reacciones + comentarios por post' + '</span>' + '</div>' + '</div>' + '<section class="table-panel">' + '<div class="panel-head">' + '<h3>Resumen por plataforma</h3>' + '</div>' + '<table class="sl-table">' + '<thead>' + '<tr>' + '<th>Red</th>' + '<th>Posts</th>' + '<th>Reacciones</th>' + '<th>Comentarios</th>' + '</tr>' + '</thead>' + '<tbody>' + (platRows || '<tr>' + '<td colspan="4" class="cell-muted">' + 'Sin datos en la ventana.' + '</td>' + '</tr>') + '</tbody>' + '</table>' + '</section>' + '<section class="table-panel">' + '<div class="panel-head">' + '<h3>Menciones por plataforma</h3>' + '</div>' + '<table class="sl-table">' + '<thead>' + '<tr>' + '<th>Red</th>' + '<th>Menciones</th>' + '<th>Autores únicos</th>' + '</tr>' + '</thead>' + '<tbody>' + (mencRows || '<tr>' + '<td colspan="3" class="cell-muted">' + 'Sin datos en la ventana.' + '</td>' + '</tr>') + '</tbody>' + '</table>' + '</section>' + '<section class="table-panel">' + '<div class="panel-head">' + '<h3>Top 10 publicaciones de la ventana</h3>' + '</div>' + '<table class="sl-table">' + '<thead>' + '<tr>' + '<th>Red</th>' + '<th>Contenido</th>' + '<th>Reacciones</th>' + '<th>Comentarios</th>' + '<th>Fecha</th>' + '</tr>' + '</thead>' + '<tbody>' + (topRows || '<tr>' + '<td colspan="5" class="cell-muted">' + 'Sin datos en la ventana.' + '</td>' + '</tr>') + '</tbody>' + '</table>' + '</section>';
    document.getElementById('f_dias').addEventListener('change', function () {
      appsmith.updateModel({
        f_dias: this.value
      });
      setTimeout(function () {
        appsmith.triggerEvent('onLoadData');
      }, 150);
    });
  }
  function initReportsModule() {
    renderReport(decodeB64(appsmith.model.reportJson));
    var last = appsmith.model.reportJson || '';
    function refresh(newModel) {
      var currentModel = newModel || appsmith.model || {};
