  function initReportsModule() {
    renderReport(
      decodeB64(
        appsmith.model.reportJson
      )
    );

    var last =
      appsmith.model.reportJson || '';

    function refresh(newModel) {
      var currentModel =
        newModel ||
        appsmith.model ||
        {};

      var now =
        currentModel.reportJson || '';

      if (now !== last) {
        last = now;

        renderReport(
          decodeB64(now)
        );
      }
    }

    if (typeof appsmith.onModelChange === 'function') {
      reportModelUnlisten =
        appsmith.onModelChange(refresh);
    } else {
      reportRefreshInterval =
        setInterval(function () {
          refresh(
            appsmith.model || {}
          );
        }, 1500);
    }

    setTimeout(function () {
      appsmith.triggerEvent('onLoadData');
    }, 300);
  }
